import { test, expect } from '@playwright/test';

test.describe('Tablet Layout - Two-Column Grid', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/tablet-layout');
  });

  test('should switch to two-column grid layout on tablet viewport', async ({ page }) => {
    // Set viewport to tablet size
    await page.setViewportSize({ width: 768, height: 1024 });

    // Verify initial layout is single column
    const singleColumnLayout = page.getByRole('region', { name: /single column/i });
    await expect(singleColumnLayout).toBeVisible();

    // Verify two-column layout is not visible
    const twoColumnLayout = page.getByRole('region', { name: /two column/i });
    await expect(twoColumnLayout).not.toBeVisible();

    // Verify tablet-specific styles are applied
    const tabletStyles = page.getByTestId('tablet-styles');
    await expect(tabletStyles).toBeVisible();

    // Verify grid items are visible in single column
    const gridItem = page.getByRole('heading', { name: /Item 1/i });
    await expect(gridItem).toBeVisible();

    // Verify grid item is not visible in two-column layout
    await expect(twoColumnLayout).not.toContainText('Item 1');

    // Verify two-column layout is visible after setting viewport
    await page.setViewportSize({ width: 1024, height: 1024 });
    await expect(twoColumnLayout).toBeVisible();

    // Verify grid items are visible in two-column layout
    await expect(gridItem).toBeVisible();

    // Verify grid item is visible in both columns
    const column1 = page.getByRole('region', { name: /column 1/i });
    const column2 = page.getByRole('region', { name: /column 2/i });
    await expect(column1).toContainText('Item 1');
    await expect(column2).toContainText('Item 1');

    // Verify responsive breakpoints are respected
    await page.setViewportSize({ width: 1280, height: 1024 });
    await expect(twoColumnLayout).toBeVisible();

    // Verify layout switches back to single column on smaller viewport
    await page.setViewportSize({ width: 640, height: 1024 });
    await expect(twoColumnLayout).not.toBeVisible();
    await expect(singleColumnLayout).toBeVisible();
  });

  test('should maintain two-column layout on tablet when resizing', async ({ page }) => {
    // Set viewport to tablet size
    await page.setViewportSize({ width: 768, height: 1024 });

    // Verify initial two-column layout is visible
    const twoColumnLayout = page.getByRole('region', { name: /two column/i });
    await expect(twoColumnLayout).toBeVisible();

    // Verify grid items are visible in two-column layout
    const gridItem = page.getByRole('heading', { name: /Item 1/i });
    await expect(gridItem).toBeVisible();

    // Resize viewport to test responsive behavior
    await page.setViewportSize({ width: 1024, height: 1024 });
    await expect(twoColumnLayout).toBeVisible();

    // Verify grid items are still visible in two-column layout
    await expect(gridItem).toBeVisible();

    // Resize viewport to test edge case
    await page.setViewportSize({ width: 1280, height: 1024 });
    await expect(twoColumnLayout).toBeVisible();

    // Verify layout switches back to single column on smaller viewport
    await page.setViewportSize({ width: 640, height: 1024 });
    await expect(twoColumnLayout).not.toBeVisible();
    await expect(singleColumnLayout).toBeVisible();
  });
});
